 28	func TestSemanticBoundaryRootTextJSONAndLimits(t *testing.T) {
 29		snapshot := strings.Replace(semanticBoundaryFixtureSnapshot(), `{"record_type":"summary"}`, `{"record_type":"relation","from_id":"gh/example/repo:go:internal/auth/token.go:function:auth.ValidateToken","to_id":"external:route:POST /tokens","type":"HANDLES_ROUTE","confidence":1}
 30	{"record_type":"summary"}`, 1)
 31		opts := boundaryRegressionFixture(t, snapshot)
 32		for _, tc := range []struct{ kind, boundary, relation string }{
 33			{"route", "GET /tokens/{id}", "HANDLES_ROUTE"},
 34			{"tool", "brain refresh", "HANDLES_TOOL"},
 35			{"workflow", "token validation", "HANDLES_WORKFLOW"},
 36		} {
 37			t.Run(tc.kind, func(t *testing.T) {
 38				out, err := execute(t, NewRootCommand(opts), "inspect", "boundaries", "--kind", tc.kind)
 39				if err != nil || !strings.Contains(out, tc.boundary) || !strings.Contains(out, tc.relation) || !strings.Contains(out, "handler auth.ValidateToken internal/auth/token.go:10-20") {
 40					t.Fatalf("boundary text: err=%v output=%q", err, out)
 41				}
 42				if tc.kind == "route" && !strings.Contains(out, "POST /tokens") {
 43					t.Fatalf("external boundary omitted: %q", out)
 44				}
 45				out, err = execute(t, NewRootCommand(opts), "inspect", "boundaries", "--kind", tc.kind, "--limit", "1", "--json")
 46				if err != nil {
 47					t.Fatal(err)
 48				}
 49				var result struct {
 50					Boundary semanticBoundaryResult `json:"boundary"`
 51				}
 52				if err := json.Unmarshal([]byte(out), &result); err != nil {
 53					t.Fatalf("JSON output: %v\n%s", err, out)
 54				}
 55				if len(result.Boundary.Boundaries) != 1 || len(result.Boundary.Handlers) != 1 || len(result.Boundary.Relations) != 1 {
 56					t.Fatalf("limit must keep one boundary with only its handler/relation: %+v", result.Boundary)
 57				}
 58				if result.Boundary.Relations[0].Type != tc.relation || result.Boundary.Handlers[0].Name != "ValidateToken" {
 59					t.Fatalf("boundary provenance mismatch: %+v", result.Boundary)
 60				}
 61			})
 62		}
 63	}
