 10	// semanticBoundaryFixtureSnapshotExternalNodes models the shape the real
 11	// `entire graph` provider emits: route/tool boundaries are external endpoint
 12	// nodes (no file path) referenced by HANDLES_* relations from in-repo handler
 13	// symbols, rather than kind-tagged in-repo symbols. The external records are
 14	// dropped at SQLite generation (only file/symbol/relation are ingested), so the
 15	// boundary identity must be recovered from the relations' external endpoints.
 16	func semanticBoundaryFixtureSnapshotExternalNodes() string {
 17		return `{"schema_version":"1.0","provider":"entire-graph","provider_version":"0.1.0","repo_key":"gh/example/repo","commit":"aaa111","tree":"tree111","capabilities":["go","routes","tools","workflows"],"warnings":[],"partial_failures":[]}
 18	{"record_type":"symbol","id":"gh/example/repo:go:internal/auth/token.go:function:auth.ValidateToken","kind":"function","name":"ValidateToken","qualified_name":"auth.ValidateToken","file_path":"internal/auth/token.go","start_line":10,"end_line":20,"signature":"func ValidateToken(token string) error","language":"Go","stable_id_version":"1"}
 19	{"record_type":"symbol","id":"gh/example/repo:go:internal/cli/root.go:function:cli.Refresh","kind":"function","name":"Refresh","qualified_name":"cli.Refresh","file_path":"internal/cli/root.go","start_line":50,"end_line":60,"signature":"func Refresh()","language":"Go","stable_id_version":"1"}
 20	{"record_type":"external","id":"external:route:/tokens/{id}","kind":"route","name":""}
 21	{"record_type":"external","id":"external:tool:brain refresh","kind":"tool","name":""}
 22	{"record_type":"external","id":"external:import:../lib/util","kind":"import","name":""}
 23	{"record_type":"relation","from_id":"gh/example/repo:go:internal/auth/token.go:function:auth.ValidateToken","to_id":"external:route:/tokens/{id}","type":"HANDLES_ROUTE","confidence":0.9}
 24	{"record_type":"relation","from_id":"gh/example/repo:go:internal/cli/root.go:function:cli.Refresh","to_id":"external:tool:brain refresh","type":"HANDLES_TOOL","confidence":0.8}
 25	{"record_type":"summary"}
 26	`
 27	}
 28	
 29	func TestSemanticBoundaryCommandsResolveExternalNodes(t *testing.T) {
 30		repoDir := t.TempDir()
 31		env := semanticTestEnv(t, repoDir)
 32		runner := semanticFixtureRunner(repoDir, semanticBoundaryFixtureSnapshotExternalNodes())
 33		cmd := NewRootCommand(Options{Version: "test-version", Env: env, Runner: runner, Now: time.Now})
 34		if _, err := execute(t, cmd, "refresh", "index", "--graph-binary", "entire"); err != nil {
 35			t.Fatalf("index: %v", err)
 36		}
 37	
 38		type boundaryReport struct {
 39			Boundary semanticBoundaryResult `json:"boundary"`
 40		}
 41		run := func(kind string) boundaryReport {
 42			t.Helper()
 43			out, err := execute(t, cmd, "inspect", "boundaries", "--kind", kind, "--json")
 44			if err != nil {
 45				t.Fatalf("%s: %v", kind, err)
 46			}
 47			var report boundaryReport
 48			if err := json.Unmarshal([]byte(out), &report); err != nil {
 49				t.Fatalf("parse %s json: %v\n%s", kind, err, out)
 50			}
 51			return report
 52		}
 53	
 54		// routes: the external:route node becomes the boundary (kind route, no file
 55		// path, name from the endpoint value); the in-repo handler is listed.
 56		routes := run("route")
 57		if len(routes.Boundary.Boundaries) != 1 {
 58			t.Fatalf("routes boundaries = %+v", routes.Boundary.Boundaries)
 59		}
 60		if b := routes.Boundary.Boundaries[0]; b.Kind != "route" || b.Name != "/tokens/{id}" || b.FilePath != "" {
 61			t.Fatalf("unexpected route boundary: %+v", b)
 62		}
 63		if len(routes.Boundary.Handlers) != 1 || !strings.Contains(routes.Boundary.Handlers[0].Name, "ValidateToken") {
 64			t.Fatalf("routes handlers = %+v", routes.Boundary.Handlers)
 65		}
 66		if len(routes.Boundary.Relations) != 1 {
 67			t.Fatalf("routes relations = %+v", routes.Boundary.Relations)
 68		}
 69	
 70		// tools: separate external:tool node; the route boundary/handler must not
 71		// leak into the tool view (kind filtering).
 72		tools := run("tool")
 73		if len(tools.Boundary.Boundaries) != 1 {
 74			t.Fatalf("tools boundaries = %+v", tools.Boundary.Boundaries)
 75		}
 76		if b := tools.Boundary.Boundaries[0]; b.Kind != "tool" || b.Name != "brain refresh" {
 77			t.Fatalf("unexpected tool boundary: %+v", b)
 78		}
 79		if len(tools.Boundary.Handlers) != 1 || !strings.Contains(tools.Boundary.Handlers[0].Name, "Refresh") {
 80			t.Fatalf("tools handlers = %+v", tools.Boundary.Handlers)
 81		}
 82	
 83		// workflows: no workflow relations -> legitimately empty (not an error,
 84		// and the import external node must never surface as a boundary).
 85		workflows := run("workflow")
 86		if len(workflows.Boundary.Boundaries) != 0 || len(workflows.Boundary.Relations) != 0 {
 87			t.Fatalf("workflows should be empty: %+v", workflows.Boundary)
 88		}
 89	
 90		// An empty boundary view must say so in text mode rather than print nothing,
 91		// so "no workflows" is distinguishable from a broken command. Use a fresh
 92		// root command so the earlier --json flag does not carry over.
 93		textCmd := NewRootCommand(Options{Version: "test-version", Env: env, Runner: runner, Now: time.Now})
 94		out, err := execute(t, textCmd, "inspect", "boundaries", "--kind", "workflow")
 95		if err != nil {
 96			t.Fatalf("workflows text: %v", err)
 97		}
 98		if !strings.Contains(out, "no workflows found in the semantic index") {
 99			t.Fatalf("workflows empty-state message missing:\n%s", out)
100		}
101	}

