  1	package cli
  2	
  3	import "testing"
  4	
  5	func TestSemanticCompletenessAxisToleratesFewParseErrors(t *testing.T) {
  6		parseFailures := make([]semanticWarning, 45)
  7		for i := range parseFailures {
  8			parseFailures[i] = semanticWarning{Code: semanticParseErrorCode, Severity: "warning", Detail: "tree-sitter syntax error nodes present"}
  9		}
 10		cases := []struct {
 11			name      string
 12			source    *semanticSourceManifest
 13			wantState string
 14		}{
 15			{
 16				name:      "few parse errors stay ok",
 17				source:    &semanticSourceManifest{Files: 1212, PartialFailures: parseFailures},
 18				wantState: "ok",
 19			},
 20			{
 21				name:      "too many parse errors degrade",
 22				source:    &semanticSourceManifest{Files: 100, PartialFailures: parseFailures},
 23				wantState: "degraded",
 24			},
 25			{
 26				name: "non-parse failure always degrades",
 27				source: &semanticSourceManifest{Files: 1212, PartialFailures: []semanticWarning{
 28					{Code: "E_SYMBOL_EXTRACTION", Severity: "warning"},
 29				}},
 30				wantState: "degraded",
 31			},
 32			{
 33				name: "intentional provider skips stay recorded without degrading",
 34				source: &semanticSourceManifest{Files: 1212, Symbols: 1, PartialFailures: []semanticWarning{
 35					{Code: semanticFileTooLargeCode, Severity: "warning"},
 36					{Code: semanticMinifiedCode, Severity: "warning"},
 37				}},
 38				wantState: "ok",
 39			},
 40			{
 41				name: "intentional skips do not consume parse error tolerance",
 42				source: &semanticSourceManifest{Files: 20, Symbols: 1, PartialFailures: []semanticWarning{
 43					{Code: semanticFileTooLargeCode, Severity: "warning"},
 44					{Code: semanticMinifiedCode, Severity: "warning"},
 45					{Code: semanticParseErrorCode, Severity: "warning"},
 46				}},
 47				wantState: "ok",
 48			},
 49			{
 50				name: "intentional skip does not hide extraction failure",
 51				source: &semanticSourceManifest{Files: 1212, Symbols: 1, PartialFailures: []semanticWarning{
 52					{Code: semanticMinifiedCode, Severity: "warning"},
 53					{Code: "E_SYMBOL_EXTRACTION", Severity: "warning"},
 54				}},
 55				wantState: "degraded",
 56			},
 57			{
 58				name: "majority intentionally skipped remains unsafe",
 59				source: &semanticSourceManifest{Files: 3, Symbols: 1, PartialFailures: []semanticWarning{
 60					{Code: semanticFileTooLargeCode, Severity: "warning"},
 61					{Code: semanticMinifiedCode, Severity: "warning"},
 62				}},
 63				wantState: "unsafe",
 64			},
 65			{
 66				name: "parsed files with zero symbols remain degraded",
 67				source: &semanticSourceManifest{Files: 2, PartialFailures: []semanticWarning{
 68					{Code: semanticMinifiedCode, Severity: "warning"},
 69				}},
 70				wantState: "degraded",
 71			},
 72			{
 73				name: "intentional skip with uncountable file set degrades",
 74				source: &semanticSourceManifest{PartialFailures: []semanticWarning{
 75					{Code: semanticMinifiedCode, Severity: "warning"},
 76				}},
 77				wantState: "degraded",
 78			},
 79			{
 80				name: "unknown casing fails closed",
 81				source: &semanticSourceManifest{Files: 1212, PartialFailures: []semanticWarning{
 82					{Code: "e_minified", Severity: "warning"},
 83				}},
 84				wantState: "degraded",
 85			},
 86			{
 87				name: "empty failure code fails closed",
 88				source: &semanticSourceManifest{Files: 1212, PartialFailures: []semanticWarning{
 89					{Severity: "warning"},
 90				}},
 91				wantState: "degraded",
 92			},
 93			{
 94				name:      "uncountable file set degrades",
 95				source:    &semanticSourceManifest{Files: 0, PartialFailures: parseFailures[:1]},
 96				wantState: "degraded",
 97			},
 98		}
 99		for _, tc := range cases {
100			t.Run(tc.name, func(t *testing.T) {
101				got := semanticCompletenessAxis(tc.source)
102				if got.State != tc.wantState {
103					t.Fatalf("state = %q, want %q (detail: %s)", got.State, tc.wantState, got.Detail)
104				}
105			})
106		}
107	}

