 13	// TestSemanticEndpointPathRecoversFieldsAroundColons pins the endpoint parse
 14	// against every ID shape entire-graph emits, including the ones where a field
 15	// legitimately contains ":" — a file path, a local repo key, and a route
 16	// symbol's qualified name.
 17	func TestSemanticEndpointPathRecoversFieldsAroundColons(t *testing.T) {
 18		t.Parallel()
 19		cases := []struct {
 20			name    string
 21			repoKey string
 22			id      string
 23			want    string
 24		}{
 25			{"symbol", "gh/ashtom/entire-brain", "gh/ashtom/entire-brain:Go:cmd/entire-brain/main.go:function:main", "cmd/entire-brain/main.go"},
 26			{"symbol lowercase language", "gh/example/repo", "gh/example/repo:go:secret/config.go:function:Secret", "secret/config.go"},
 27			{"kind marker in path before future kind", "gh/example/repo", "gh/example/repo:Go:dir:function:file.go:new_kind:F", ""},
 28			{"ambiguous qualified name", "gh/example/repo", "gh/example/repo:Go:file.go:function:Name:Part", ""},
 29			{"future kind", "gh/example/repo", "gh/example/repo:Go:main.go:future_kind:F", "main.go"},
 30			{"multiple colons in file path", "gh/example/repo", "gh/example/repo:Go:dir:a:b/file.go:function:F", "dir:a:b/file.go"},
 31			{"ambiguous kind markers", "gh/example/repo", "gh/example/repo:Go:dir:function:file.go:function:F", ""},
 32			{"colon in file path", "gh/example/repo", "gh/example/repo:Python:od:d/mod.py:function:f", "od:d/mod.py"},
 33			{"colon in file path, dotted leaf", "gh/example/repo", "gh/example/repo:Python:od:mod.py:function:f", "od:mod.py"},
 34			{"colon in repo key", "local/My:Repo", "local/My:Repo:Go:main.go:function:main", "main.go"},
 35			{"colon in qualified name", "gh/example/repo", "gh/example/repo:JavaScript:src/routes.js:route:GET /users/:id", "src/routes.js"},
 36			{"colon in path and qualified name", "gh/example/repo", "gh/example/repo:JavaScript:od:d/routes.js:route:GET /users/:id", "od:d/routes.js"},
 37			{"file endpoint", "gh/example/repo", "gh/example/repo:file:internal/auth/token.go", "internal/auth/token.go"},
 38			{"file endpoint with colon in path", "gh/example/repo", "gh/example/repo:file:od:d/mod.py", "od:d/mod.py"},
 39			{"external import", "gh/example/repo", "external:import:archive/tar", ""},
 40			{"external route", "gh/example/repo", "external:route:/repo", ""},
 41			{"endpoint from another repo", "gh/example/repo", "gh/other/repo:Go:main.go:function:main", ""},
 42			{"opaque endpoint", "gh/example/repo", "public", ""},
 43			{"empty id", "gh/example/repo", "", ""},
 44			{"unknown repo key", "", "gh/example/repo:Go:main.go:function:main", ""},
 45		}
 46		for _, tc := range cases {
 47			t.Run(tc.name, func(t *testing.T) {
 48				t.Parallel()
 49				if got := semanticEndpointPath(tc.repoKey, tc.id); got != tc.want {
 50					t.Fatalf("semanticEndpointPath(%q, %q) = %q, want %q", tc.repoKey, tc.id, got, tc.want)
 51				}
 52			})
 53		}
 54	}
