 56	// semanticColonPathSnapshot is a provider snapshot whose Python file lives at a
 57	// path containing ":" — legal on every filesystem Brain supports. Nothing in it
 58	// is ignored by "od": the real path is "od:d/mod.py", not "od/…".
 59	func semanticColonPathSnapshot() string {
 60		return `{"schema_version":"1.0","provider":"entire-graph","provider_version":"0.1.0","repo_key":"gh/example/repo","commit":"aaa111","tree":"tree111","capabilities":["go"],"warnings":[],"partial_failures":[]}
 61	{"record_type":"file","id":"gh/example/repo:file:od:d/mod.py","path":"od:d/mod.py","blob":"abc123","language":"Python"}
 62	{"record_type":"symbol","id":"gh/example/repo:Python:od:d/mod.py:function:load","kind":"function","name":"load","qualified_name":"load","file_path":"od:d/mod.py","start_line":1,"end_line":4,"language":"Python","stable_id_version":"1"}
 63	{"record_type":"symbol","id":"gh/example/repo:Go:internal/auth/token.go:function:auth.ValidateToken","kind":"function","name":"ValidateToken","qualified_name":"auth.ValidateToken","file_path":"internal/auth/token.go","start_line":10,"end_line":20,"language":"Go","stable_id_version":"1"}
 64	{"record_type":"relation","from_id":"gh/example/repo:Go:internal/auth/token.go:function:auth.ValidateToken","to_id":"gh/example/repo:Python:od:d/mod.py:function:load","type":"CALLS","confidence":1}
 65	{"record_type":"summary","warnings":[],"partial_failures":[]}
 66	`
 67	}
 68	
 69	// semanticIgnoredFileEndpointSnapshot references two ignored files only through
 70	// file endpoint IDs. entire-graph resolves imports and co-change pairs to
 71	// "<repo-key>:file:<path>" endpoints for files it never emits a record for, so
 72	// the ignored-ID set cannot see them and the endpoint ID is the only signal
 73	// that the relation touches an ignored file.
 74	func semanticIgnoredFileEndpointSnapshot() string {
 75		return `{"schema_version":"1.0","provider":"entire-graph","provider_version":"0.1.0","repo_key":"gh/example/repo","commit":"aaa111","tree":"tree111","capabilities":["go"],"warnings":[],"partial_failures":[]}
 76	{"record_type":"file","id":"gh/example/repo:file:internal/auth/token.go","path":"internal/auth/token.go","blob":"abc123","language":"Go"}
 77	{"record_type":"relation","from_id":"gh/example/repo:file:internal/auth/token.go","to_id":"gh/example/repo:file:secret/config.go","type":"IMPORTS","confidence":1}
 78	{"record_type":"relation","from_id":"gh/example/repo:file:internal/auth/token.go","to_id":"gh/example/repo:file:od:d/secret.py","type":"IMPORTS","confidence":1}
 79	{"record_type":"summary","warnings":[],"partial_failures":[]}
 80	`
 81	}
 82	
 83	func semanticEndpointPathIndex(t *testing.T, brainignore, snapshot string) (*exportManifest, string) {
 84		t.Helper()
 85		repoDir := t.TempDir()
 86		if err := os.WriteFile(filepath.Join(repoDir, ".brainignore"), []byte(brainignore), 0o600); err != nil {
 87			t.Fatalf("write .brainignore: %v", err)
 88		}
 89		env := semanticTestEnv(t, repoDir)
 90		runner := semanticFixtureRunner(repoDir, snapshot)
 91		cmd := &cobra.Command{Use: "index"}
 92		if err := runSemanticIndex(cmd.Context(), cmd, Options{Env: env, Runner: runner, Now: time.Now}, semanticIndexOptions{graphBinary: "entire"}, repoDir); err != nil {
 93			t.Fatalf("index: %v", err)
 94		}
 95		brainDir := filepath.Join(env.PluginDataDir, repoStoreDirName, "gh", "example", "repo")
 96		manifest, err := loadBrainManifest(brainDir)
 97		if err != nil {
 98			t.Fatalf("load manifest: %v", err)
 99		}
100		data, err := os.ReadFile(filepath.Join(brainDir, filepath.FromSlash(manifest.Sources.Semantic.SnapshotPath)))
101		if err != nil {
102			t.Fatalf("read snapshot: %v", err)
103		}
104		return manifest, string(data)
105	}
106	
107	// A ".brainignore" rule for the directory "od" must not redact a file named
108	// "od:d/mod.py", which is not inside it. Reading the path out of a fixed
109	// colon-separated field of the symbol ID saw "od" and dropped every relation
110	// touching the file, while keeping the file and its symbols — a silent,
111	// one-sided loss of the relation graph.
112	func TestSemanticIndexKeepsRelationsForColonPathOutsideIgnoredDirectory(t *testing.T) {
113		manifest, snapshot := semanticEndpointPathIndex(t, "od\n", semanticColonPathSnapshot())
114		if manifest.Sources.Semantic.Symbols != 2 {
115			t.Fatalf("symbols in a non-ignored file were dropped: %+v", manifest.Sources.Semantic)
116		}
117		if manifest.Sources.Semantic.Relations != 1 {
118			t.Fatalf("relation between two non-ignored files was redacted: %+v", manifest.Sources.Semantic)
119		}
120		if !strings.Contains(snapshot, `"type":"CALLS"`) {
121			t.Fatalf("relation missing from the persisted snapshot:\n%s", snapshot)
122		}
123	}
124	
125	// The same file path, now genuinely ignored, must be redacted.
126	func TestSemanticIndexDropsRelationsForIgnoredColonPath(t *testing.T) {
127		manifest, snapshot := semanticEndpointPathIndex(t, "od:d/\n", semanticColonPathSnapshot())
128		if manifest.Sources.Semantic.Relations != 0 {
129			t.Fatalf("relation touching an ignored file survived: %+v", manifest.Sources.Semantic)
130		}
131		if strings.Contains(snapshot, "od:d/mod.py") {
132			t.Fatalf("ignored path leaked into the snapshot:\n%s", snapshot)
133		}
134	}
135	
136	// A file endpoint ID has three colon-separated fields, so the old "at least
137	// five fields" guard skipped every one of them: a relation naming an ignored
138	// file through "<repo-key>:file:<path>" was written into the brain verbatim.
139	func TestSemanticIndexDropsRelationsToIgnoredFileEndpoints(t *testing.T) {
140		manifest, snapshot := semanticEndpointPathIndex(t, "secret/\nod:d/\n", semanticIgnoredFileEndpointSnapshot())
141		if manifest.Sources.Semantic.Relations != 0 {
142			t.Fatalf("relations to ignored file endpoints survived: %+v", manifest.Sources.Semantic)
143		}
144		if strings.Contains(snapshot, "secret/config.go") || strings.Contains(snapshot, "od:d/secret.py") {
145			t.Fatalf("ignored path leaked into the snapshot:\n%s", snapshot)
146		}
147	}
148	
149	// filterSemanticSnapshot re-filters an already persisted snapshot and shares the
150	// endpoint parse, so it must reach the same verdicts.
151	func TestFilterSemanticSnapshotHonorsColonPathEndpoints(t *testing.T) {
152		t.Parallel()
153		kept := brainIgnore{patterns: []string{"od"}}
154		_, counts, _, err := filterSemanticSnapshot([]byte(semanticColonPathSnapshot()), kept, t.TempDir())
155		if err != nil {
156			t.Fatalf("filter: %v", err)
157		}
158		if counts.Relations != 1 {
159			t.Fatalf("relation between two non-ignored files was redacted: %+v", counts)
160		}
161	
162		ignored := brainIgnore{patterns: []string{"od:d/"}}
163		_, counts, filtered, err := filterSemanticSnapshot([]byte(semanticColonPathSnapshot()), ignored, t.TempDir())
164		if err != nil {
165			t.Fatalf("filter: %v", err)
166		}
167		if counts.Relations != 0 {
168			t.Fatalf("relation touching an ignored file survived: %+v", counts)
169		}
170		if strings.Contains(string(filtered), "od:d/mod.py") {
171			t.Fatalf("ignored path leaked into the filtered snapshot:\n%s", filtered)
172		}
173	}
174	
175	func TestSemanticMultipleColonPathIgnoreDecisions(t *testing.T) {
176		snapshot := strings.ReplaceAll(semanticColonPathSnapshot(), "od:d/mod.py", "dir:a:b/file.go")
177		manifest, _ := semanticEndpointPathIndex(t, "dir\n", snapshot)
178		if manifest.Sources.Semantic.Relations == 0 {
179			t.Fatal("allowed relation was dropped")
180		}
181		manifest, _ = semanticEndpointPathIndex(t, "dir:a:b/\n", snapshot)
182		if manifest.Sources.Semantic.Relations != 0 {
183			t.Fatal("ignored relation retained")
184		}
185	}
186	
187	func TestSemanticDuplicateIDCannotClearIgnoreVerdict(t *testing.T) {
188		lines := strings.Split(semanticColonPathSnapshot(), "\n")
189		duplicate := strings.Replace(lines[2], `"file_path":"od:d/mod.py"`, `"file_path":"secret/hidden.py"`, 1)
190		snapshot := lines[0] + "\n" + duplicate + "\n" + strings.Join(lines[1:], "\n")
191		manifest, _ := semanticEndpointPathIndex(t, "secret/\n", snapshot)
192		if manifest.Sources.Semantic.Relations != 0 {
193			t.Fatal("streaming ingest cleared the earlier ignore verdict")
194		}
195		_, counts, _, err := filterSemanticSnapshot([]byte(snapshot), brainIgnore{patterns: []string{"secret/"}}, t.TempDir())
196		if err != nil {
197			t.Fatal(err)
198		}
199		if counts.Relations != 0 {
200			t.Fatal("snapshot filtering cleared the earlier ignore verdict")
201		}
202	}

