  1	package cli
  2	
  3	import (
  4		"encoding/json"
  5		"io"
  6		"os"
  7		"path/filepath"
  8		"strings"
  9		"testing"
 10		"time"
 11	
 12		"github.com/spf13/cobra"
 13	)
 14	
 15	// The provider is the only witness to its own coverage, and a file it never
 16	// considered is in none of its warnings, none of its partial failures and none
 17	// of its counts. entire-graph applies Go build constraints for the HOST
 18	// platform, so on darwin a //go:build linux file -- or any _linux.go /
 19	// _windows.go file -- is dropped before parsing while the summary still reports
 20	// parsed_files == files, partial_failures == 0 and completeness_level "ok".
 21	//
 22	// Reproduced against the real provider (entire-graph dev, darwin/arm64) with a
 23	// 7-file repository: a_linux.go, b_linux.go, c_tagged.go (//go:build linux) and
 24	// f_windows.go were all absent from `entire graph snapshot`, which reported
 25	// warnings: [] and partial_failures: 0.
 26	//
 27	// This test pins the brain's answer to that: the tracked file the provider
 28	// parsed the NEIGHBOURS of, skipped, and said nothing about is named in the
 29	// manifest. Before the fix the manifest carried no record of it at all.
 30	func TestSemanticIndexNamesAFileTheProviderSilentlySkipped(t *testing.T) {
 31		repoDir := t.TempDir()
 32		env := semanticTestEnv(t, repoDir)
 33	
 34		runner := semanticFixtureRunner(repoDir, semanticCoverageSnapshot())
 35		runner.responses[fakeCommandKey("git", "ls-tree", "-r", "--name-only", "-z", "aaa111")] = fakeCommandResponse{
 36			stdout: strings.Join([]string{
 37				"internal/shop/pricing.go",
 38				"internal/shop/pricing_windows.go",
 39				"go.mod",
 40				"vendor/other/vendored.go",
 41			}, "\x00"),
 42		}
 43	
 44		source := semanticCoverageIndex(t, env, runner, repoDir)
 45	
 46		got := semanticWarningPathsWithCode(source.Warnings, semanticUnreportedSkipCode)
 47		if len(got) != 1 || got[0] != "internal/shop/pricing_windows.go" {
 48			t.Fatalf("the silently skipped file is not named in the manifest; unreported-skip warnings = %v\nall warnings: %s", got, semanticWarningDump(source.Warnings))
 49		}
 50	
 51		// The warning has to say what is LOST, not merely that something happened:
 52		// a reader who only sees a code cannot tell whether the file mattered.
 53		for _, warning := range source.Warnings {
 54			if warning.Code != semanticUnreportedSkipCode {
 55				continue
 56			}
 57			if !strings.Contains(warning.Effect, "not parsed") {
 58				t.Fatalf("the warning does not say the file went unparsed: %+v", warning)
 59			}
 60		}
 61	
 62		// Narrowness is the whole licence for this check. A vendored tree the
 63		// provider parsed nothing from, and a file type it never handles, must not
 64		// be flagged -- otherwise the brain is second-guessing the provider's
 65		// file-selection policy instead of reporting its silence.
 66		for _, p := range got {
 67			if p == "go.mod" || strings.HasPrefix(p, "vendor/") {
 68				t.Fatalf("a file the provider was never expected to parse was flagged: %q", p)
 69			}
 70		}
 71	}
 72	
 73	// The control, in the same shape: when the provider emits every tracked file,
 74	// the index must stay silent. A coverage check that cries wolf on a healthy
 75	// repository is worse than none.
 76	func TestSemanticIndexIsSilentWhenTheProviderParsedEverything(t *testing.T) {
 77		repoDir := t.TempDir()
 78		env := semanticTestEnv(t, repoDir)
 79	
 80		runner := semanticFixtureRunner(repoDir, semanticCoverageSnapshot())
