    33			{"colon in file path, dotted leaf", "gh/example/repo", "gh/example/repo:Python:od:mod.py:function:f", "od:mod.py"},
    34			{"colon in repo key", "local/My:Repo", "local/My:Repo:Go:main.go:function:main", "main.go"},
    35			{"colon in qualified name", "gh/example/repo", "gh/example/repo:JavaScript:src/routes.js:route:GET /users/:id", "src/routes.js"},
    36			{"colon in path and qualified name", "gh/example/repo", "gh/example/repo:JavaScript:od:d/routes.js:route:GET /users/:id", "od:d/routes.js"},
